import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Solución de problemas","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/troubleshooting.md","filePath":"es/guide/troubleshooting.md","lastUpdated":1793173149000}`),a={name:`es/guide/troubleshooting.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="solucion-de-problemas" tabindex="-1">Solución de problemas <a class="header-anchor" href="#solucion-de-problemas" aria-label="Permalink to “Solución de problemas”">​</a></h1><p>Esta página recopila los problemas habituales y cómo resolverlos.</p><h2 id="la-aplicacion-no-arranca-o-se-cierra-al-iniciarse" tabindex="-1">La aplicación no arranca o se cierra al iniciarse <a class="header-anchor" href="#la-aplicacion-no-arranca-o-se-cierra-al-iniciarse" aria-label="Permalink to “La aplicación no arranca o se cierra al iniciarse”">​</a></h2><p>Síntomas: Sudoku no se abre, se cierra inmediatamente o muestra un error inesperado.</p><p>Pasos que puedes probar:</p><ol><li>Comprueba que tu dispositivo cumple los requisitos mínimos (iOS/iPadOS 16 o posterior, macOS 15 o posterior).</li><li>Fuerza el cierre de la app y vuelve a abrirla.</li><li>Reinicia tu dispositivo.</li><li>Vuelve a instalar la app desde la App Store.</li><li>Si el problema persiste, abre un issue en el repositorio del proyecto con los detalles.</li></ol><h2 id="problemas-de-rendimiento" tabindex="-1">Problemas de rendimiento <a class="header-anchor" href="#problemas-de-rendimiento" aria-label="Permalink to “Problemas de rendimiento”">​</a></h2><p>Si el juego va lento o con tirones:</p><ol><li>Cierra otras aplicaciones pesadas.</li><li>En Mac, revisa el Monitor de Actividad para detectar un uso elevado de CPU.</li><li>En dispositivos más antiguos, prueba con una dificultad más sencilla (Fácil o Medio).</li></ol><h2 id="la-sincronizacion-con-icloud-no-funciona" tabindex="-1">La sincronización con iCloud no funciona <a class="header-anchor" href="#la-sincronizacion-con-icloud-no-funciona" aria-label="Permalink to “La sincronización con iCloud no funciona”">​</a></h2><p>Si tu progreso no se sincroniza entre dispositivos:</p><ol><li>Comprueba que has iniciado sesión con el mismo Apple ID en todos los dispositivos.</li><li>Verifica que iCloud Drive está activado en Ajustes del Sistema (Mac) o en Ajustes (iOS/iPadOS).</li><li>Confirma que tienes una conexión a internet activa.</li><li>Desactiva y vuelve a activar iCloud para Sudoku en Ajustes → [Tu nombre] → iCloud → Apps que usan iCloud.</li><li>Reinicia todos los dispositivos e inténtalo de nuevo.</li></ol><h2 id="game-center-no-conecta" tabindex="-1">Game Center no conecta <a class="header-anchor" href="#game-center-no-conecta" aria-label="Permalink to “Game Center no conecta”">​</a></h2><p>Si los logros o las clasificaciones de Game Center no se actualizan:</p><ol><li>Comprueba que has iniciado sesión en Game Center (Ajustes → Game Center en iOS; Ajustes del Sistema en Mac).</li><li>Revisa tu conexión a internet.</li><li>Cierra la sesión de Game Center y vuelve a iniciarla.</li></ol><h2 id="ver-los-registros" tabindex="-1">Ver los registros <a class="header-anchor" href="#ver-los-registros" aria-label="Permalink to “Ver los registros”">​</a></h2><p>Para diagnosticar cierres inesperados, los registros de la aplicación son útiles. En las compilaciones en sandbox (App Store) para Mac, revisa:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~/Library/Containers/com.w3cub.sudoku/Data/Library/Logs/sudoku/sudoku.log</span></span></code></pre></div><p>En iOS/iPadOS, conecta tu dispositivo a un Mac y usa Console.app para ver los registros, filtrando por «Sudoku».</p><h2 id="restablecer-la-app" tabindex="-1">Restablecer la app <a class="header-anchor" href="#restablecer-la-app" aria-label="Permalink to “Restablecer la app”">​</a></h2><p>Para restablecer los ajustes y borrar los datos locales (Mac):</p><ol><li>Cierra Sudoku</li><li>Elimina el contenedor (cuidado: esto borra todos los ajustes, estadísticas y partidas guardadas):</li></ol><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.sudoku</span></span></code></pre></div><ol start="3"><li>Vuelve a abrir Sudoku y configúralo de nuevo.</li></ol><p>En iPhone/iPad, elimina y vuelve a instalar la app para restablecer todos los datos.</p><p><strong>Nota</strong>: si usas la sincronización con iCloud, restablecer en un dispositivo puede volver a descargar los datos de iCloud tras reiniciar la app. Para restablecerlo todo en todos los dispositivos, puede que tengas que hacerlo en cada uno de ellos.</p><h2 id="informar-de-un-problema" tabindex="-1">Informar de un problema <a class="header-anchor" href="#informar-de-un-problema" aria-label="Permalink to “Informar de un problema”">​</a></h2><p>Cuando abras un issue, incluye:</p><ul><li>Tipo de dispositivo (iPhone, iPad o Mac)</li><li>Versión del sistema operativo (Ajustes → General → Información)</li><li>Versión de Sudoku (Ajustes → Acerca de)</li><li>Pasos para reproducir el problema</li><li>Registros o capturas de pantalla, si los tienes</li></ul><p>Esto ayuda a los mantenedores a identificar y corregir el problema más rápido.</p>`,30)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};